describe('WebSocket Real-time UI Updates', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should establish WebSocket connection and update UI in real-time', () => {
    // Intercept WebSocket connection
    cy.intercept('GET', 'ws://api.example.com/ws').as('websocketConnection');
    cy.wait('@websocketConnection');

    // Verify initial UI state
    cy.get('[data-testid="status-indicator"]').should('contain', 'Connected');
    cy.get('[data-testid="message-count"]').should('contain', '0');

    // Mock WebSocket message
    cy.intercept('GET', 'ws://api.example.com/ws', {
      statusCode: 200,
      body: {
        type: 'message',
        payload: {
          content: 'New message received',
          timestamp: Date.now()
        }
      }
    }).as('newMessage');

    // Wait for WebSocket message and verify UI update
    cy.wait('@newMessage');
    cy.get('[data-testid="message-count"]').should('contain', '1');
    cy.get('[data-testid="message-content"]').should('contain', 'New message received');
    cy.get('[data-testid="message-timestamp"]').should('be.visible');

    // Mock another WebSocket message
    cy.intercept('GET', 'ws://api.example.com/ws', {
      statusCode: 200,
      body: {
        type: 'message',
        payload: {
          content: 'Another update',
          timestamp: Date.now()
        }
      }
    }).as('anotherMessage');

    // Wait for second message and verify UI update
    cy.wait('@anotherMessage');
    cy.get('[data-testid="message-count"]').should('contain', '2');
    cy.get('[data-testid="message-content"]').should('contain', 'Another update');
  });

  it('should handle WebSocket connection errors and display appropriate error state', () => {
    // Intercept WebSocket connection and simulate failure
    cy.intercept('GET', 'ws://api.example.com/ws', {
      statusCode: 500,
      body: {
        error: 'Internal Server Error'
      }
    }).as('websocketConnectionError');

    // Attempt to connect and wait for error
    cy.wait('@websocketConnectionError');

    // Verify error state is displayed
    cy.get('[data-testid="status-indicator"]').should('contain', 'Disconnected');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Connection failed');

    // Verify UI does not show message count
    cy.get('[data-testid="message-count"]').should('not.exist');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="retry-button"]').should('contain', 'Retry Connection');

    // Verify retry button can be clicked
    cy.get('[data-testid="retry-button"]').click();
    cy.get('[data-testid="status-indicator"]').should('contain', 'Connecting...');
  });
});
